// src/pages/CashBack/CashBackCard.jsx
import React from 'react';
import { FaFire } from 'react-icons/fa';
import styles from './CashBackCard.module.css';

const CashBackCard = ({ discount, name, image, link }) => {
  const handleCheckPrice = () => {
    console.log(`Checking price for ${name}`);
    window.location.href = link;
  };

  return (
    <div className={styles.cashBackCard}>
      <div className={styles.discountBadge}>
        <FaFire className={styles.fireIcon} />
        {discount}
      </div>
      <div className={styles.cardContent}>
        <img src={image} alt={name} className={styles.productImage} />
        <div className={styles.textSection}>
          <h3 className={styles.productName}>{name}</h3>
        </div>
      </div>
      <button className={styles.checkPriceButton} onClick={handleCheckPrice}>
        Check price
      </button>
    </div>
  );
};

export default CashBackCard;
